    in.finish();std::set<std::uint32_t> attached;for(auto& [id,state]:buttons){auto parent=result.find(state->dialog);if(parent==result.end() || !dialogs.contains(parent->second))throw std::runtime_error("Invalid button dialog mapping");state->dialog=parent->second;}for(auto& [id,list]:children)for(auto stable:list){auto found=result.find(stable);if(found==result.end() || !buttons.contains(found->second) || buttons.at(found->second)->dialog!=id || !attached.insert(found->second).second)throw std::runtime_error("Invalid dialog button mapping");dialogs.at(id)->buttons.push_back(found->second);}if(attached.size()!=buttons.size())throw std::runtime_error("Unattached dialog button");objects_.reserve(objects_.size()+pending.size());for(auto& object:pending)objects_.push_back(std::move(object));dialogs_.swap(dialogs);buttons_.swap(buttons);defeatConditions_.swap(conditions);scriptDialogsRebuilt_=true;return result;
